public class TreeNode
{
    public int Val;
    public TreeNode? Left;
    public TreeNode? Right;
    public TreeNode(int val) { Val = val; }
}
public static class LevelOrderTree
{
    // Builds a tree from a level-order array; null marks a missing child.
    public static TreeNode? Build(int?[] values)
    {
        if (values.Length == 0 || values[0] is not int rootValue) return null;
        var root = new TreeNode(rootValue);
        var queue = new Queue<TreeNode>();
        queue.Enqueue(root);
        var i = 1;
        while (queue.Count > 0 && i < values.Length)
        {
            var node = queue.Dequeue();
            if (values[i] is int leftValue)
            {
                node.Left = new TreeNode(leftValue);
                queue.Enqueue(node.Left);
            }
            i++;
            if (i < values.Length && values[i] is int rightValue)
            {
                node.Right = new TreeNode(rightValue);
                queue.Enqueue(node.Right);
            }
            i++;
        }
        return root;
    }

    // The tree as a level-order list with null for missing children, trailing nulls trimmed.
    public static List<int?> ToList(TreeNode? root)
    {
        var result = new List<int?>();
        var queue = new Queue<TreeNode?>();
        queue.Enqueue(root);
        while (queue.Count > 0)
        {
            var node = queue.Dequeue();
            if (node is null) { result.Add(null); continue; }
            result.Add(node.Val);
            queue.Enqueue(node.Left);
            queue.Enqueue(node.Right);
        }
        while (result.Count > 0 && result[^1] is null) result.RemoveAt(result.Count - 1);
        return result;
    }
}

